const chartData = {
    "labels": [
        "Founder's Personal Network",
        "Engineering Meetup Post",
        "Employer Volunteer Program",
        "University CS Club",
        "Parent Referral"
    ],
    "datasets": [
        {
            "label": "Candidates in a 3-week window",
            "data": [
                3,
                7,
                4,
                4,
                2
            ],
            "backgroundColor": "#4A90D9",
            "yAxisID": "y"
        },
        {
            "label": "Passed the qualification trial (%)",
            "data": [
                100,
                43,
                75,
                50,
                100
            ],
            "backgroundColor": "#F5A623",
            "yAxisID": "y1"
        }
    ]
};

const chartOptions = {
    "responsive": true,
    "maintainAspectRatio": false,
    "plugins": {
        "legend": {
            "position": "top",
            "align": "end",
            "labels": {
                "boxWidth": 14,
                "font": {
                    "size": 12
                }
            }
        },
        "tooltip": {
            "titleFont": {
                "size": 13
            },
            "bodyFont": {
                "size": 13
            }
        }
    },
    "scales": {
        "x": {
            "ticks": {
                "font": {
                    "size": 11
                },
                "maxRotation": 30
            }
        },
        "y": {
            "beginAtZero": true,
            "ticks": {
                "font": {
                    "size": 12
                }
            },
            "position": "left",
            "title": {
                "display": true,
                "text": "Candidates generated",
                "font": {
                    "size": 13
                }
            }
        },
        "y1": {
            "beginAtZero": true,
            "max": 100,
            "position": "right",
            "grid": {
                "drawOnChartArea": false
            },
            "title": {
                "display": true,
                "text": "Passed trial (%)",
                "font": {
                    "size": 13
                }
            }
        }
    }
};

const ctx = document.getElementById('chart');
const chart = new Chart(ctx, {
    type: "bar",
    data: chartData,
    options: chartOptions
});

// Checkbox controls mirror the legend, so a series can be toggled without
// knowing that clicking a legend entry does that.
document.querySelectorAll('[data-dataset]').forEach(el => {
    el.addEventListener('change', () => {
        const i = parseInt(el.dataset.dataset, 10);
        chart.setDatasetVisibility(i, el.checked);
        chart.update();
    });
    // apply the initial state declared in the data file
    const i = parseInt(el.dataset.dataset, 10);
    chart.setDatasetVisibility(i, el.checked);
});
chart.update();

// Dropdown controls call onControl, and buttons call onAction. A sim defines
// whichever it needs in its extraJs block; both are optional.
document.querySelectorAll('select[data-control]').forEach(el => {
    el.addEventListener('change', () => {
        if (typeof onControl === 'function') onControl(el.dataset.control, el.value);
    });
});

document.querySelectorAll('button[data-action]').forEach(el => {
    el.addEventListener('click', () => {
        if (typeof onAction === 'function') onAction(el.dataset.action);
    });
});
